/* LF-NOTEBOOK v2.0.0 */
/* 林锋手帐本体。由酒馆助手脚本从 git 拉取后，注入到每一楼的前端 iframe 里运行。
   AI 输出的文本只用 textContent 写进页面，绝不 innerHTML。 */
(function () {
'use strict';
var W = window, D = document, P = W.parent;
if (W.__lfNotebookLive) return;
W.__lfNotebookLive = true;
var HOST = P.__lfNotebook || {};
var VERSION = '2.0.0';

/* ---------- 浏览页：搜索站点（要换站点只改这里；搜什么由主模型每条自己写的“搜索关键词”决定） ---------- */
var SEARCH_URL = 'https://www.pornhub.com/video/search?search=';
var API_BASE = 'https://www.pornhub.com/webmasters/';
var EMBED_BASE = 'https://www.pornhub.com/embed/';
var PROBE_KEY = 'lf-notebook:probe';
var PROBE_OK_MS = 24 * 3600 * 1000, PROBE_NO_MS = 10 * 60 * 1000; // 通：记一天；不通：记十分钟（改完配置重启酒馆后很快生效）

/* ---------- 小工具 ---------- */
function h(tag, cls, text) { var e = D.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; }
function svgEl(html, cls) { var e = D.createElement('span'); e.className = 'svg' + (cls ? ' ' + cls : ''); e.innerHTML = html; return e; }
function clip(s, n) { s = String(s == null ? '' : s).replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n) + '…' : s; }
function djb(s) { var x = 5381; for (var i = 0; i < s.length; i++) x = ((x << 5) + x + s.charCodeAt(i)) | 0; return (x >>> 0).toString(36); }
function getCtx() { try { return (W.SillyTavern || P.SillyTavern).getContext(); } catch (e) { return null; } }
function msgIndex() {
  var n = NaN;
  try { n = Number(W.getCurrentMessageId()); } catch (e) { /* 取不到就看 iframe 名字 */ }
  if (!isFinite(n)) {
    var m = String(W.name || (W.frameElement && W.frameElement.id) || '').match(/^TH-message--(\d+)--/);
    n = m ? Number(m[1]) : NaN;
  }
  return n;
}
var NUM = { '一': 1, '二': 2, '两': 2, '三': 3, '四': 4, '五': 5, '六': 6, '七': 7, '八': 8, '九': 9, '十': 10 };
function toNum(s) {
  s = String(s || '');
  var d = s.match(/\d+/); if (d) return Number(d[0]);
  var c = s.match(/[一二两三四五六七八九十]+/); if (!c) return 0;
  var t = c[0];
  if (t.length === 1) return NUM[t];
  if (t.charAt(0) === '十') return 10 + (NUM[t.charAt(1)] || 0);
  if (t.charAt(1) === '十') return NUM[t.charAt(0)] * 10 + (NUM[t.charAt(2)] || 0);
  return NUM[t.charAt(0)] || 0;
}

/* ---------- 解析 AI 写的手帐（单行 + 竖线分隔，不用 JSON） ---------- */
var SECTION_KEYS = [['勤务', 'duty'], ['侦查', 'case'], ['厨房', 'kitchen'], ['证物', 'bag'], ['封条', 'seal'], ['浏览', 'browse']];
function parseNotebook(block) {
  var out = { overtime: null, duty: [], 'case': [], kitchen: [], bag: [], seal: [], browse: [] };
  var cur = null;
  String(block || '').split(/\r?\n/).forEach(function (line) {
    var raw = line.trim();
    if (!raw) return;
    var hasSep = /[｜|]/.test(raw);
    if (!hasSep) {
      var hd = raw.match(/^[#*>\s\[【<＜(（]*(勤务|侦查|厨房|证物|封条|浏览)/);
      if (hd) { cur = SECTION_KEYS.filter(function (k) { return k[0] === hd[1]; })[0][1]; }
      return;
    }
    if (!cur) return;
    var body = raw.replace(/^(?:[-*•·]|\d+[.、)）])\s*/, '');
    var f = body.split(/\s*[｜|]\s*/).map(function (x) { return x.trim(); });
    while (f.length && !f[f.length - 1]) f.pop();
    if (!f.length) return;
    if (cur === 'duty') {
      if (f[0] === '加班') { out.overtime = { yes: !/^(否|没|无|不)/.test(f[1] || '') && !!f[1], note: f.slice(2).join('，') || '' }; return; }
      var tags = ['警情', '她', '日常'];
      var tag = tags.indexOf(f[0]) >= 0 ? f.shift() : '警情';
      if (f.length < 2) return;
      out.duty.push({ tag: tag, title: f[0], front: f[1], back: f.slice(2).join('，') });
    } else if (cur === 'case') {
      if (f.length < 2) return;
      out['case'].push({ crime: f[0], record: f[1], level: f[2] || '', retort: f.slice(3).join('，') });
    } else if (cur === 'kitchen') {
      if (f.length < 2) return;
      var rate = toNum(f[4]);
      out.kitchen.push({ dish: f[0], nth: toNum(f[1]) || 1, what: f[2] || '', excuse: f[3] || '', rate: Math.max(0, Math.min(100, rate)) });
    } else if (cur === 'bag') {
      if (f.length < 2) return;
      out.bag.push(f.length >= 3 ? { item: f[0], origin: f[1], note: f.slice(2).join('，') } : { item: f[0], origin: '', note: f[1] });
    } else if (cur === 'browse') {
      /* 搜索关键词｜标题｜时间｜被抓包时的反应；只有 3 段当作 标题｜时间｜反应（没有关键词，搜索退回用标题）；2 段当作 标题｜反应 */
      if (f.length < 2) return;
      var bi;
      if (f.length >= 4) bi = { kw: f[0], title: f[1], time: f[2], excuse: f.slice(3).join('，') };
      else if (f.length === 3) bi = { kw: '', title: f[0], time: f[1], excuse: f[2] };
      else bi = { kw: '', title: f[0], time: '', excuse: f[1] };
      if (bi.title) out.browse.push(bi);
    } else if (cur === 'seal') {
      var kinds = ['醋', '想', '荤'];
      if (f.length === 1) out.seal.push({ kind: '想', text: f[0] });
      else out.seal.push({ kind: kinds.indexOf(f[0]) >= 0 ? f[0] : '想', text: (kinds.indexOf(f[0]) >= 0 ? f.slice(1) : f).join('，') });
    }
  });
  ['duty', 'case', 'kitchen', 'bag', 'seal'].forEach(function (k) { out[k] = out[k].slice(0, 6); });
  out.browse = out.browse.slice(0, 8);
  return out;
}

W.__lfParse = parseNotebook; /* 供测试调用 */

/* ---------- 取楼层、存状态 ---------- */
var IDX = msgIndex();
var CTX = getCtx();
var BLOCK = null;
(function () {
  try {
    var m = CTX && CTX.chat[IDX];
    var mm = String((m && m.mes) || '').match(/<notebook>([\s\S]*?)<\/notebook>/i);
    BLOCK = mm ? mm[1] : null;
  } catch (e) { BLOCK = null; }
})();
var ST = null, saveTimer = 0;
function loadState(hash) {
  var all = {};
  try { all = W.getVariables({ type: 'message', message_id: IDX }) || {}; } catch (e) { all = {}; }
  var s = all.lf_notebook;
  if (!s || s.h !== hash) s = { h: hash, open: 0, page: 0, stamp: {}, stars: {}, seal: {}, bag: 0, thread: {}, shown: {}, vid: {} };
  if (!s.shown) s.shown = {};
  if (!s.vid) s.vid = {};
  ST = s;
}
function save() {
  clearTimeout(saveTimer);
  saveTimer = setTimeout(function () {
    try {
      var all = W.getVariables({ type: 'message', message_id: IDX }) || {};
      all.lf_notebook = ST;
      W.replaceVariables(all, { type: 'message', message_id: IDX });
    } catch (e) { /* 存不了就算了，不影响看 */ }
  }, 200);
}

/* ---------- 设置（副 API） ---------- */
var MEM_SET = { endpoint: '', key: '', model: '' };
function getSettings() {
  try { if (HOST.getSettings) return HOST.getSettings(); } catch (e) { /* 走兜底 */ }
  try { return JSON.parse(P.localStorage.getItem('lf-notebook:settings') || '{}'); } catch (e) { return MEM_SET; }
}
function putSettings(s) {
  try { if (HOST.saveSettings) { HOST.saveSettings(s); return; } } catch (e) { /* 走兜底 */ }
  MEM_SET = s;
  try { P.localStorage.setItem('lf-notebook:settings', JSON.stringify(s)); } catch (e) { /* 存储被拒 */ }
}
function endpointURL(v) {
  var raw = String(v || '').trim(), u;
  try { u = new URL(raw); } catch (e) { throw new Error('副 API 地址要填完整，例如 https://你的服务商/v1'); }
  if (!/^https?:$/.test(u.protocol) || u.username || u.password || u.search || u.hash) throw new Error('副 API 地址需要是完整的 http(s) 地址，不能带账号、问号或 #。');
  if (u.protocol !== 'https:' && ['localhost', '127.0.0.1', '[::1]'].indexOf(u.hostname) < 0) throw new Error('远程副 API 请用 https；只有本机 localhost 可以用 http。');
  u.pathname = u.pathname.replace(/\/+$/, '');
  if (!/\/chat\/completions$/.test(u.pathname)) u.pathname += '/chat/completions';
  return u.href;
}

/* ---------- 互动：副 API 或主 API ---------- */
/* ---------- 副 API 的上下文：全部从酒馆当前上下文读，不写死角色（取法照 Rifugio iMessage 小手机 phone.js 的 makeRequest / readPersona） ---------- */
function charData() { try { var c = CTX.characters && CTX.characters[CTX.characterId]; return c ? { c: c, d: c.data || c } : null; } catch (e) { return null; } }
function charName() { var x = charData(); return (x && (x.d.name || x.c.name)) || (CTX && CTX.name2) || '角色'; }
function userName() { return (CTX && CTX.name1) || '用户'; }
function expandMacros(v) {
  try { return String(CTX.substituteParams ? CTX.substituteParams(v) : v).split('{{' + 'user}}').join(userName()).split('{{' + 'char}}').join(charName()); } catch (e) { return String(v); }
}
/* 角色卡字段：优先用酒馆上下文自带的 getCharacterCardFields()（酒馆 1.19 public/script.js getCharacterCardFields，
   经 public/scripts/st-context.js 暴露在 SillyTavern.getContext() 上）：返回 description / personality / scenario /
   mesExamples（示例对话）/ persona（用户人设），已展开宏，群聊和聊天内覆盖也由酒馆处理。
   取不到时退回小手机 phone.js makeRequest 的做法：characters[characterId] 的 data[k] || character[k] + substituteParams。 */
function cardFields() {
  try { if (CTX && typeof CTX.getCharacterCardFields === 'function') { var f = CTX.getCharacterCardFields(); if (f) return f; } } catch (e) { /* 走兜底 */ }
  var x = charData(), out = { description: '', personality: '', scenario: '', mesExamples: '', persona: '' };
  if (x) ['description', 'personality', 'scenario'].forEach(function (k) { out[k] = expandMacros(x.d[k] || x.c[k] || ''); });
  if (x) out.mesExamples = expandMacros(x.d.mes_example || x.c.mes_example || '');
  return out;
}
/* 角色设定：描述 / 性格 / 场景，各段换行拼起来，最多 18000 字（长度同小手机） */
function cardText() {
  var f = cardFields();
  return [f.description, f.personality, f.scenario].filter(function (v) { return v && String(v).trim(); }).join('\n').slice(0, 18000);
}
/* 示例对话（卡里的 mes_example），最多 6000 字 */
function exampleText() { try { return String(cardFields().mesExamples || '').trim().slice(0, 6000); } catch (e) { return ''; } }
/* 用户人设：酒馆“用户设定”的描述。优先 getCharacterCardFields().persona，兜底小手机 readPersona：powerUserSettings.persona_description */
function personaText() {
  try { var v = cardFields().persona; if (v && String(v).trim()) return String(v).trim().slice(0, 6000); } catch (e) { /* 走兜底 */ }
  try { var v2 = CTX.powerUserSettings && CTX.powerUserSettings.persona_description; return typeof v2 === 'string' ? expandMacros(v2).slice(0, 6000) : ''; } catch (e) { return ''; }
}
/* 最近三楼正文（当前楼和前两楼），去掉手帐块，最多 10000 字 */
function nearbyText() {
  try {
    return CTX.chat.slice(Math.max(0, IDX - 2), IDX + 1).map(function (m) {
      return (m.is_user ? userName() : charName()) + '：' + String(m.mes == null ? '' : m.mes).replace(/<notebook>[\s\S]*?<\/notebook>/gi, '');
    }).join('\n').slice(-10000);
  } catch (e) { return ''; }
}
/* 当前生效的世界书：用酒馆自己的 getWorldInfoPrompt（干跑，不触发事件），拿它按关键词/常开算出来的条目；
   带有 <notebook> 的条目是手帐自己的输出格式规则，不给副 API 看。最多 8000 字 */
async function worldText() {
  try {
    if (!CTX || typeof CTX.getWorldInfoPrompt !== 'function') return '';
    var chat = CTX.chat.slice(Math.max(0, IDX - 10), IDX + 1).map(function (m) { return String(m.mes == null ? '' : m.mes); }).reverse();
    var r = await CTX.getWorldInfoPrompt(chat, Number(CTX.maxContext) || 8192, true);
    var parts = [r.worldInfoBefore, r.worldInfoAfter];
    (r.worldInfoDepth || []).forEach(function (d) { (d.entries || []).forEach(function (e) { parts.push(e); }); });
    return parts.map(function (x) { return typeof x === 'string' ? x : ''; }).filter(function (x) { return x.trim() && !/<notebook>/i.test(x); }).map(expandMacros).join('\n').slice(0, 8000);
  } catch (e) { return ''; }
}
function replyText(body) {
  if (body && body.error) throw new Error('副 API 返回了错误，没有生成回复。请检查模型是否可用。');
  var c = body && body.choices && body.choices[0];
  if (!c) throw new Error('副 API 返回的格式不对：没有 choices，需要 Chat Completions 接口。');
  var v = c.message ? c.message.content : c.text;
  if (Array.isArray(v)) v = v.map(function (p) { return typeof p === 'string' ? p : (p && typeof p.text === 'string' ? p.text : ''); }).join('');
  v = String(v || '').replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
  var fence = v.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i); if (fence) v = fence[1].trim();
  if (/^[\[{]/.test(v)) {
    try {
      var j = JSON.parse(v);
      var arr = Array.isArray(j) ? j : (Array.isArray(j.messages) ? j.messages : [j.text || j.content || '']);
      v = arr.map(function (x) { return typeof x === 'string' ? x : (x && (x.text || x.content)) || ''; }).join('\n').trim();
    } catch (e) { /* 不是 JSON 就当普通文字 */ }
  }
  if (!v) throw new Error('副 API 请求成功，但回复是空的。换个模型或重试。');
  return v.slice(0, 600);
}
async function askSecondary(S, itemInfo, userText, kind) {
  var url = endpointURL(S.endpoint);
  if (!String(S.model || '').trim()) throw new Error('副 API 缺模型名，请到手帐设置里补上。');
  var name = charName(), user = userName();
  var card = cardText(), example = exampleText(), world = await worldText(), persona = personaText(), near = nearbyText();
  /* 不写任何性格：角色怎么反应由角色卡、世界书、用户人设和最近剧情决定 */
  var system = '你正在扮演 ' + name + '。' + user + ' 刚在你的' + (kind === 'browse' ? '手帐里“浏览记录”那一页' : '手帐') + '上对你说了一句话。' +
    '按下面的角色设定、世界书、用户人设和最近剧情，推演你此刻的反应；保留角色本人的性格、口气和关系，沿用上下文里真实存在的爱称。' +
    '只输出角色说的话，1 到 3 句，短，口语；不写动作旁白，不替' + user + '回答，不输出 JSON、HTML 或代码块，不自称 AI。\n' +
    '角色设定：\n' + (card || '（没读到角色卡，不补造设定）') + '\n' +
    (example ? '示例对话：\n' + example + '\n' : '') +
    (world ? '世界书（当前生效）：\n' + world + '\n' : '') +
    '用户人设资料：\n' + (persona || '（没读到用户人设，不补造资料）') + '\n' +
    (near ? '最近三楼正文（仅作故事参考）：\n' + near + '\n' : '') +
    '手帐里这一条：' + itemInfo;
  var ctl = new P.AbortController(), timer = setTimeout(function () { ctl.abort(); }, 60000);
  try {
    var key = String(S.key || '').trim();
    var headers = { 'Content-Type': 'application/json' };
    if (key) headers.Authorization = 'Bearer ' + key;
    var res = await P.fetch(url, {
      method: 'POST', headers: headers, signal: ctl.signal, credentials: 'omit', referrerPolicy: 'no-referrer',
      body: JSON.stringify({ model: String(S.model).trim(), stream: false, temperature: 0.9, messages: [{ role: 'system', content: system }, { role: 'user', content: userText }] })
    });
    if (!res.ok) throw new Error('副 API 返回 HTTP ' + res.status + '，请检查地址、钥匙和模型。');
    var body; try { body = await res.json(); } catch (e) { throw new Error('副 API 返回的不是 JSON，请检查地址是否是 Chat Completions 接口。'); }
    return replyText(body);
  } catch (e) {
    if (e && e.name === 'AbortError') throw new Error('副 API 超过 60 秒没回，已取消。');
    if (e instanceof TypeError) throw new Error('副 API 连不上：检查网络，或服务商没开跨域（CORS）。');
    throw e;
  } finally { clearTimeout(timer); }
}
function sendToMain(text) {
  var pd = P.document, ta = pd.getElementById('send_textarea'), btn = pd.getElementById('send_but');
  if (!ta || !btn) return '没找到酒馆的输入框，这句没发出去。';
  var stop = pd.getElementById('mes_stop');
  if (stop && P.getComputedStyle(stop).display !== 'none') return charName() + '还在写上一条，等写完再点。';
  var old = ta.value;
  ta.value = text;
  ta.dispatchEvent(new P.Event('input', { bubbles: true }));
  btn.click();
  if (old) setTimeout(function () { if (!ta.value) { ta.value = old; ta.dispatchEvent(new P.Event('input', { bubbles: true })); } }, 120);
  return '';
}
var pending = {};
/* 一次互动：key 标这一条（如 case:0），box 是显示回复的地方 */
async function interact(key, userText, itemInfo, box, btn) {
  if (pending[key]) return;
  var S = getSettings() || {};
  var notice = box.querySelector('.notice');
  function say(t, bad) { notice.textContent = t || ''; notice.className = 'notice' + (bad ? ' bad' : ''); notice.style.display = t ? 'block' : 'none'; }
  if (!String(S.endpoint || '').trim()) {
    var err = sendToMain('【手帐互动】\n正在看：' + itemInfo + '\n' + userName() + '说：' + userText + '\n请按当前角色设定回应用户这句话。');
    say(err || '已发进聊天，' + charName() + '会在正文里回你。', !!err);
    return !err;
  }
  pending[key] = 1; if (btn) btn.disabled = true; say(charName() + '翻本子中…');
  try {
    var reply = await askSecondary(S, itemInfo, userText, key.indexOf('browse:') === 0 ? 'browse' : '');
    var list = ST.thread[key] || (ST.thread[key] = []);
    list.push({ u: userText, r: reply }); if (list.length > 6) list.shift();
    save(); say(''); renderThread(box, key); return true;
  } catch (e) { say(e.message || String(e), true); return false; }
  finally { pending[key] = 0; if (btn) btn.disabled = false; }
}
function renderThread(box, key) {
  var t = box.querySelector('.thread'); t.textContent = '';
  (ST.thread[key] || []).slice(-2).forEach(function (m) {
    var a = h('div', 'tm me'); a.textContent = m.u; t.appendChild(a);
    var b = h('div', 'tm lf'); b.textContent = m.r; t.appendChild(b);
  });
}
function threadBox() { var b = h('div', 'ibox'); b.appendChild(h('div', 'thread')); var n = h('div', 'notice'); n.setAttribute('role', 'status'); n.setAttribute('aria-live', 'polite'); n.style.display = 'none'; b.appendChild(n); return b; }


/* 用户输入保持原文；记录上下文另行提供，绝不替用户编一句固定台词。 */
function composer(key, itemInfo, placeholder) {
  var wrap = h('div', 'conversation');
  var ib = threadBox(); renderThread(ib, key); wrap.appendChild(ib);
  var form = h('form', 'compose');
  var label = h('label', 'compose-label', '给' + charName() + '的小纸条');
  var input = h('textarea', 'free-input'); input.rows = 2; input.placeholder = placeholder;
  input.setAttribute('aria-label', '对' + charName() + '说的话');
  input.value = (ST.draft && ST.draft[key]) || '';
  input.addEventListener('input', function () { (ST.draft || (ST.draft = {}))[key] = input.value; save(); });
  label.appendChild(input); form.appendChild(label);
  var line = h('div', 'compose-bottom'); line.appendChild(h('span', 'hint', '写什么都可以 ♡'));
  var send = h('button', 'btn send', '递小纸条 ↗'); send.type = 'submit'; line.appendChild(send); form.appendChild(line);
  input.addEventListener('keydown', function (e) { if (e.key === 'Enter' && (e.ctrlKey || e.metaKey) && !e.isComposing) { e.preventDefault(); form.requestSubmit(); } });
  form.addEventListener('submit', async function (e) {
    e.preventDefault();
    if (pending[key]) return;
    var text = input.value;
    if (!text.trim()) { var notice = ib.querySelector('.notice'); notice.textContent = '先写一句话，再递给他吧。'; notice.className = 'notice'; notice.style.display = 'block'; input.focus(); return; }
    var ok = await interact(key, text, itemInfo, ib, send);
    if (ok && input.value === text) { input.value = ''; if (ST.draft) delete ST.draft[key]; save(); }
  });
  wrap.appendChild(form); return wrap;
}

/* ---------- 浏览页：探测本酒馆的跨域代理，经它搜视频（能播档） ---------- */
/* 酒馆 1.19：开了 enableCorsProxy 后，同源的 /proxy/<完整网址> 会替浏览器去取；网址要整段 encodeURIComponent，
   不编码的话 ? 后面的参数会被酒馆丢掉。没开时 /proxy/ 返回 404。 */
function proxyUrl(u) { return new URL('/proxy/' + encodeURIComponent(u), P.location.href).href; }
async function proxyJson(u, ms) {
